design.skinstate_shape:
struct FlowSkinState {
  // 1-bit Excel-native edit mode: is an inline edit buffer currently open on the focus chip?
  // When true, ALL keystrokes (/, ?, ], [, E) are verbatim EditContent text; only Esc/Enter exit.
  editing: Option<EditBuffer>,            // EditBuffer { node: NodeId, draft: String }
  // explain-unfold: which nodes are expanded in the explain stack (memoized render on (NodeId,value_epoch))
  unfolded: HashSet<NodeId>,
  // baseline cache for delta badges + Esc-to-baseline (host snapshot of content_text/value scalar at interaction start)
  baseline: HashMap<NodeId, (String /*content_text*/, String /*computed_value scalar text*/)>,
  // scenario chips 1-9: each a named override map applied via EditContentDeferred batch + Recalculate
  scenarios: Vec<ScenarioChip>,            // ScenarioChip { label: String, overrides: HashMap<NodeId, String> }
  active_scenario: Option<usize>,
  // persistent fill-rule template cards (Clay promote-to-template), re-grabbable across sessions
  templates: Vec<FillRule>,                // FillRule { name: String, source: NodeId, targets: Vec<NodeId> }
  // last dependency-walk frontier so ]/[ accumulation survives re-render; cleared on Esc
  lit_subgraph: Vec<NodeId>,
  // cached topo layout of the focused slice, invalidated only when dependency_shape_snapshot_id changes
  layout_cache: Option<(String /*dependency_shape_snapshot_id*/, Vec<NodeId>)>,
  // lane viewport anchor so the focused Sentence slice restores on remount
  lane_anchor: Option<NodeId>,
  // omnibox/query state is transient (not persisted): current_query, grammar_mode
}
